"source_stock":0,"proposed_stock":0,"inventory_assignment":"none","repairdesk_product_id":"42459871","inventory_index_id":"50795821","variant_image_url":"https://dghyt15qon7us.cloudfront.net/images/productTheme/Inventory/small/0.65416400%201732337241.jpg","group_image_url":"https://dghyt15qon7us.cloudfront.net/images/productTheme/Inventory/small/1643172433.jpg","cost_rule":"Confirmed: Z-Fold / Z-Flip Case"}},{"sku":"TM8-TAB-9601","slug":"tm8-tab-9601","name":"Flip Case for iPad 10.2-inch (Gen 7/8/9) - Red","brand":"Apple","model":"iPad 10.2-inch (Gen 7/8/9)","short_description":"Flip Case in Red.","condition_label":"Brand New","compatibility":"iPad 7th Gen 10.2; iPad 8th Gen 10.2; iPad 9th Gen 10.2","cost_price":4,"retail_price":39,"image_url":"https://dghyt15qon7us.cloudfront.net/images/productTheme/Inventory/small/0.20748200%201732336879.jpg","stock_quantity":0,"is_visible":false,"is_pos_visible":false,"upc":"2999000096015","product_group_code":"TM8-GRP-IPAD-102-GEN789-FLC","variant_name":"Red","variant_color":"Red","source_system":"repairdesk_tablet_cases","source_external_id":"9601","source_category_path":"iPad 10.2 Inch","import_status":"review","source_metadata":{"original_name":"ipad 10.2 red flip case","source_stock":1,"proposed_stock":0,"inventory_assignment":"none","repairdesk_product_id":"42459868","inventory_index_id":"50795809","variant_image_url":"https://dghyt15qon7us.cloudfront.net/images/productTheme/Inventory/small/0.20748200%201732336879.jpg","group_image_url":"https://dghyt15qon7us.cloudfront.net/images/productTheme/Inventory/small/1703654690.jpg","cost_rule":"Confirmed: Owner cost override"}}]$catalog$::jsonb) as x(
    sku text,
    slug text,
    name text,
    brand text,
    model text,
    short_description text,
    condition_label text,
    compatibility text,
    cost_price numeric,
    retail_price numeric,
    image_url text,
    stock_quantity integer,
    is_visible boolean,
    is_pos_visible boolean,
    upc text,
    product_group_code text,
    variant_name text,
    variant_color text,
    source_system text,
    source_external_id text,
    source_category_path text,
    import_status text,
    source_metadata jsonb
  )
)
insert into public.products (
  sku, slug, name, brand, model, category_id, short_description,
  condition_label, compatibility, cost_price, retail_price, image_url,
  stock_quantity, is_visible, is_pos_visible, upc, product_group_id,
  variant_name, variant_color, source_system, source_external_id,
  source_category_path, import_status, source_metadata
)
select
  input.sku,
  input.slug,
  input.name,
  input.brand,
  input.model,
  category.id,
  input.short_description,
  input.condition_label,
  nullif(input.compatibility, ''),
  input.cost_price,
  input.retail_price,
  nullif(input.image_url, ''),
  0,
  false,
  false,
  input.upc,
  product_group.id,
  input.variant_name,
  input.variant_color,
  input.source_system,
  input.source_external_id,
  input.source_category_path,
  input.import_status,
  input.source_metadata
from input
join public.categories category on category.slug = 'ipad-tablet-cases'
join public.product_groups product_group on product_group.code = input.product_group_code
on conflict (sku) do update
set name = excluded.name,
    brand = excluded.brand,
    model = excluded.model,
    category_id = excluded.category_id,
    short_description = excluded.short_description,
    condition_label = excluded.condition_label,
    compatibility = excluded.compatibility,
    cost_price = excluded.cost_price,
    retail_price = excluded.retail_price,
    image_url = excluded.image_url,
    upc = excluded.upc,
    product_group_id = excluded.product_group_id,
    variant_name = excluded.variant_name,
    variant_color = excluded.variant_color,
    source_system = excluded.source_system,
    source_external_id = excluded.source_external_id,
    source_category_path = excluded.source_category_path,
    import_status = case when products.import_status = 'active' then products.import_status else excluded.import_status end,
    is_visible = case when products.import_status = 'active' then products.is_visible else false end,
    is_pos_visible = case when products.import_status = 'active' then products.is_pos_visible else false end,
    source_metadata = excluded.source_metadata,
    updated_at = timezone('utc'::text, now());

commit;
